/* Invoice presentation choices do not modify saved billing amounts. */
const invoiceStyles=[{id:'classic',name:'Classic',description:'Traditional bordered invoice with clear sections.'},{id:'modern',name:'Modern',description:'Colored header and lighter tables.'},{id:'compact',name:'Compact',description:'Smaller spacing for invoices with many items.'}];
let invoiceStyleOverrides={};
function selectedInvoiceStyle(key,id){let value=invoiceStyleOverrides[key+'|'+id]||db.settings.invoiceStyle||'classic';return invoiceStyles.some(s=>s.id===value)?value:'classic'}
function invoiceStyleColor(){return /^#[0-9a-f]{6}$/i.test(db.settings.invoiceAccent||'')?db.settings.invoiceAccent:'#1d4ed8'}
function applyInvoiceStyle(sheet,style){if(!sheet)return;for(let s of invoiceStyles)sheet.classList.remove('invoiceStyle-'+s.id);sheet.classList.add('invoiceStyle-'+style);sheet.style.setProperty('--invoice-accent',invoiceStyleColor())}
const invoiceBeforeStyles=invoice;
invoice=function(key,id){invoiceBeforeStyles(key,id);let sheet=$('#modalBody .invoice');if(!sheet)return;let style=selectedInvoiceStyle(key,id);applyInvoiceStyle(sheet,style);let controls=$('#modalBody .invoiceFormatControls');if(controls){let label=document.createElement('label');label.className='invoiceStyleChoice';label.innerHTML=`A4 Style <select id="previewInvoiceStyle" aria-label="Invoice style">${opts(invoiceStyles.map(s=>({value:s.id,label:s.name})),style)}</select>`;controls.appendChild(label);$('#previewInvoiceStyle').onchange=e=>{invoiceStyleOverrides[key+'|'+id]=e.target.value;applyInvoiceStyle(sheet,e.target.value)}}};
const settingsBeforeInvoiceStyles=settingsPage;
settingsPage=function(){return settingsBeforeInvoiceStyles()+`<section class="panel"><div class="panelhead"><h2>Invoice Formatting</h2></div><div class="panelbody"><p>Choose a default A4 invoice style. GST, item discounts, payment details, QR and stamp use the same saved bill data in every style.</p><form id="invoiceStyleSettings"><div class="invoiceStyleCards">${invoiceStyles.map(s=>`<label class="invoiceStyleCard"><input type="radio" name="invoiceStyle" value="${s.id}" ${(db.settings.invoiceStyle||'classic')===s.id?'checked':''}><strong>${s.name}</strong><div class="invoiceMini invoiceMini-${s.id}" aria-hidden="true"><b>BIKE DOCTOR</b><div></div><div></div><div></div><small>INVOICE · TOTAL</small></div><span>${s.description}</span></label>`).join('')}</div><label class="field"><span>Modern Invoice Accent Color</span><input type="color" name="invoiceAccent" value="${invoiceStyleColor()}" style="width:90px"></label><div class="toolbar" style="margin-top:16px"><button type="submit" class="btn">Save Invoice Format</button><button type="button" class="btn secondary" id="previewInvoiceFormat">Preview on a Saved Invoice</button></div><p>Use the A4 Style selector inside an invoice to compare styles without changing the saved default. Thermal receipts retain their dedicated 58 / 80 mm layout.</p></form></div></section>`};
const renderBeforeInvoiceStyles=render;
render=function(){renderBeforeInvoiceStyles();if(page!=='settings'||!$('#invoiceStyleSettings'))return;let form=$('#invoiceStyleSettings');form.onsubmit=e=>{e.preventDefault();let values=new FormData(form),style=values.get('invoiceStyle'),accent=values.get('invoiceAccent');if(!invoiceStyles.some(s=>s.id===style)||!/^#[0-9a-f]{6}$/i.test(accent))return toast('Choose an invoice style and valid color.');let previous=structuredClone(db.settings);db.settings.invoiceStyle=style;db.settings.invoiceAccent=accent;if(save('Invoice format saved')===false){db.settings=previous;return}invoiceStyleOverrides={}};$('#previewInvoiceFormat').onclick=()=>{let key=db.jobs.length?'jobs':db.sales.length?'sales':null;if(!key)return toast('Create a job card or sale first to preview its invoice.');let style=form.querySelector('[name="invoiceStyle"]:checked')?.value||'classic',id=db[key][0].id;invoiceStyleOverrides[key+'|'+id]=style;invoice(key,id)}};
render();
